import React, { useCallback, useEffect, useRef, useState } from 'react';
import { Anvil, Download, Film, FolderOpen, Image as ImageIcon, Layers, Loader2, Plus, Sparkles, Trash2, X } from '../icons.jsx';
import { toFileUrl } from '../store.js';
import ElevenLabsStudio from './ElevenLabsStudio.jsx';

// Forge — Cutflow's AI generation panel. Photos and short videos are generated by the
// user's own providers (free Pollinations for photos, their Gemini key for the rest) and
// land on this PC in a shelf. Nothing is generated locally; the panel says so, and provider
// errors are shown exactly as the provider sent them.
export default function ForgePanel(props) {
  const [status, setStatus] = useState({ hasGeminiKey: null });
  const [catalog, setCatalog] = useState(null);
  const [mode, setMode] = useState('photo');
  const [prompt, setPrompt] = useState('');
  const [photoModel, setPhotoModel] = useState('pollinations');
  const [videoModel, setVideoModel] = useState('veo-3.1-fast-generate-001');
  const [ratio, setRatio] = useState('9:16');
  const [duration, setDuration] = useState(5);
  const [jobs, setJobs] = useState([]);
  const [shelf, setShelf] = useState([]);
  const [animateFrom, setAnimateFrom] = useState(null);
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);
  const timer = useRef(null);

  const refresh = useCallback(async () => {
    const [j, s] = await Promise.all([window.api.forgeJobs(), window.api.forgeList()]);
    if (Array.isArray(j)) setJobs(j);
    if (Array.isArray(s)) setShelf(s);
  }, []);

  useEffect(() => {
    let live = true;
    window.api.forgeStatus().then((s) => live && setStatus(s || { hasGeminiKey: false }));
    window.api.forgeCatalog().then((c) => live && setCatalog(c));
    refresh();
    timer.current = setInterval(refresh, 1500);
    return () => { live = false; clearInterval(timer.current); };
  }, [refresh]);

  const hasKey = !!status.hasGeminiKey;
  const models = catalog ? (mode === 'photo' ? catalog.photoModels : catalog.videoModels) : [];
  const modelId = mode === 'photo' ? photoModel : videoModel;
  const setModelId = mode === 'photo' ? setPhotoModel : setVideoModel;
  const ratios = catalog ? (mode === 'photo' ? catalog.photoRatios : catalog.videoRatios) : ['9:16'];

  const generate = async () => {
    setError('');
    setBusy(true);
    const res = await window.api.forgeStart({
      kind: mode, prompt, modelId, ratio, duration,
      ...(animateFrom && mode === 'video' ? { startImagePath: animateFrom.path } : {}),
    });
    setBusy(false);
    if (res?.error) { setError(res.error); return; }
    refresh();
  };

  const addToMedia = async (entry) => {
    if ((props.media || []).some((m) => m.path === entry.path)) return;
    const [res] = await window.api.probePaths([entry.path]);
    if (res && !res.error) props.dispatch({ type: 'addMedia', items: [res] });
  };

  const animate = (entry) => {
    setAnimateFrom(entry);
    setMode('video');
    if (!prompt.trim()) setPrompt(entry.prompt || '');
  };

  const running = jobs.filter((j) => j.status === 'running');
  const recent = jobs.filter((j) => j.status !== 'running').slice(0, 4);

  return (
    <div className="pad-block forge">
      <div className="forge-head">
        <span className="tab-title"><Anvil size={15} /> Forge</span>
      </div>
      <p className="muted small">Generation runs on your provider account — nothing is generated on this PC. Photos are free via Pollinations; Gemini models use the key saved for the AI assistant.</p>

      <div className="seg-tabs" role="tablist" aria-label="Forge mode">
        <button className={mode === 'photo' ? 'on' : ''} role="tab" aria-selected={mode === 'photo'} onClick={() => setMode('photo')}><ImageIcon size={13} /> Photo</button>
        <button className={mode === 'video' ? 'on' : ''} role="tab" aria-selected={mode === 'video'} onClick={() => setMode('video')}><Film size={13} /> Video</button>
      </div>

      {mode === 'video' && status.hasGeminiKey === false ? (
        <div className="forge-nokey">
          <p><strong>Video needs your Gemini key.</strong> Veo runs on your Google AI account — Forge reuses the same key as the AI assistant, so there is nothing new to set up.</p>
          <button className="btn btn-primary btn-sm" onClick={() => props.onOpenSettings?.()}>Open Settings → AI assistant</button>
          <p className="muted small">Photos still work without a key, via the free provider.</p>
        </div>
      ) : (
        <>
          <label className="forge-label" htmlFor="forge-prompt">Prompt</label>
          <textarea id="forge-prompt" className="forge-prompt" rows={3} value={prompt} onChange={(e) => setPrompt(e.target.value)}
            placeholder={mode === 'photo' ? 'A lighthouse at dusk, waves crashing, cinematic…' : 'A drone shot glides over a coastal town at sunrise…'} />
          {animateFrom && mode === 'video' && (
            <div className="forge-startframe">
              <img src={toFileUrl(animateFrom.path)} alt="" />
              <span>Starting frame: {animateFrom.prompt?.slice(0, 42) || animateFrom.file}</span>
              <button className="icon-btn" aria-label="Clear starting frame" onClick={() => setAnimateFrom(null)}><X size={13} /></button>
            </div>
          )}
          <label className="forge-label" htmlFor="forge-model">Model</label>
          <select id="forge-model" className="forge-select" value={modelId} onChange={(e) => setModelId(e.target.value)}>
            {models.map((m) => (
              <option key={m.id} value={m.id} disabled={m.needsKey && !hasKey}>
                {m.name}{m.needsKey && !hasKey ? ' — needs your Gemini key' : ''}
              </option>
            ))}
          </select>
          <label className="forge-label">Ratio</label>
          <div className="chips" role="group" aria-label="Ratio">
            {ratios.map((r) => (
              <button key={r} className={`chip ${ratio === r ? 'on' : ''}`} aria-pressed={ratio === r} onClick={() => setRatio(r)}>{r}</button>
            ))}
          </div>
          {mode === 'video' && (
            <>
              <label className="forge-label">Duration</label>
              <div className="chips" role="group" aria-label="Duration">
                {(catalog?.videoDurations || [5, 8]).map((d) => (
                  <button key={d} className={`chip ${duration === d ? 'on' : ''}`} aria-pressed={duration === d} onClick={() => setDuration(d)}>{d}s</button>
                ))}
              </div>
            </>
          )}
          {error && <p className="error-text">{error}</p>}
          <button className="btn btn-primary forge-go" disabled={busy || !prompt.trim()} onClick={generate}>
            {busy ? <Loader2 size={14} className="spin" /> : <Sparkles size={14} />} Generate {mode}
          </button>
        </>
      )}

      {(running.length > 0 || recent.length > 0) && (
        <div className="forge-jobs">
          {running.map((j) => (
            <div key={j.id} className="forge-job">
              <Loader2 size={13} className="spin" />
              <span className="forge-job-prompt">{j.kind === 'video' ? '🎞' : '🖼'} {j.prompt.slice(0, 40)}</span>
              <span className="forge-job-bar" aria-hidden="true"><span /></span>
              <button className="btn btn-ghost btn-sm" onClick={() => window.api.forgeCancel(j.id).then(refresh)}>Cancel</button>
            </div>
          ))}
          {recent.map((j) => (
            <div key={j.id} className={`forge-job ${j.status}`}>
              <span className="forge-job-prompt">{j.kind === 'video' ? '🎞' : '🖼'} {j.prompt.slice(0, 40)}</span>
              {j.status === 'done' && <span className="forge-job-state ok">Done</span>}
              {j.status === 'cancelled' && <span className="forge-job-state">Cancelled</span>}
              {j.status === 'error' && <span className="forge-job-state err">{j.error}</span>}
            </div>
          ))}
        </div>
      )}

      <div className="tpl-sec-head">
        <span className="tab-title">Generated shelf</span>
        <span className="muted small">kept on this PC</span>
      </div>
      {shelf.length === 0 ? (
        <p className="empty-note">Nothing forged yet — describe a photo or a clip above, and it lands here.</p>
      ) : (
        <div className="forge-grid">
          {shelf.map((e) => (
            <div key={e.id} className="forge-card">
              <span className="forge-thumb">
                {e.kind === 'video'
                  ? <video src={toFileUrl(e.path)} muted loop playsInline onMouseEnter={(ev) => ev.currentTarget.play()} onMouseLeave={(ev) => ev.currentTarget.pause()} />
                  : <img src={toFileUrl(e.path)} alt="" draggable={false} />}
              </span>
              <span className="forge-card-prompt" title={e.prompt}>{e.prompt}</span>
              <span className="forge-card-actions">
                <button title="Add to media library" aria-label="Add to media library" onClick={() => addToMedia(e)}><Download size={13} /></button>
                <button title="Add to timeline" aria-label="Add to timeline" onClick={() => props.onAddFile?.(e.path, 'main')}><Plus size={13} /></button>
                <button title="Add as overlay" aria-label="Add as overlay" onClick={() => props.onAddFile?.(e.path, 'overlay')}><Layers size={13} /></button>
                {e.kind === 'photo' && (
                  <button title={hasKey ? 'Animate this photo (Veo image-to-video)' : 'Animate needs your Gemini key — Veo animates the photo'} aria-label="Animate this photo"
                    onClick={() => animate(e)}><Film size={13} /></button>
                )}
                <button title="Reveal in folder" aria-label="Reveal in folder" onClick={() => window.api.forgeReveal(e.id)}><FolderOpen size={13} /></button>
                <button title="Delete" aria-label="Delete" onClick={() => window.api.forgeRemove(e.id).then(refresh)}><Trash2 size={13} /></button>
              </span>
            </div>
          ))}
        </div>
      )}

      <ElevenLabsStudio {...props} forgeShelf={shelf} />
    </div>
  );
}
